import{_ as o,a0 as d,w as p,s as r,ao as n,I as i,x as s,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何解决 Linux 中“磁盘空间不足”的问题 | LCTT x X-CMD","titleTemplate":false,"description":"如何解决 Linux 中“磁盘空间不足”的问题 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解决 Linux 中“磁盘空间不足”的问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解决 Linux 中“磁盘空间不足”的问题 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171115 How to Fix the ‘No Space Left on Device- Error on Linux","title":"如何解决 Linux 中“磁盘空间不足”的问题","tag":"201801","desc":""},"relativePath":"201801/20171115 How to Fix the ‘No Space Left on Device- Error on Linux.md","filePath":"[post].md"}'),u={name:"201801/20171115 How to Fix the ‘No Space Left on Device- Error on Linux.md"};function h(k,e,c,g,f,m){const t=d("Link");return p(),r("div",null,[e[19]||(e[19]=n('<h1 id="如何解决-linux-中-磁盘空间不足-的问题" tabindex="-1">如何解决 Linux 中“磁盘空间不足”的问题 <a class="header-anchor" href="#如何解决-linux-中-磁盘空间不足-的问题" aria-label="Permalink to “如何解决 Linux 中“磁盘空间不足”的问题”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-feat.jpg" alt=""></p><p>明明有很多剩余空间，但 Linux 系统依然提示没有空间剩余。为什么会这样呢？Linux 偶尔会有一些令人沮丧的模糊的错误消息出现，而这就是其中一种。不过这种错误通常都是由某几种因素导致的。</p><h3 id="通过-du-和-df-检查磁盘空间" tabindex="-1">通过 du 和 df 检查磁盘空间 <a class="header-anchor" href="#通过-du-和-df-检查磁盘空间" aria-label="Permalink to “通过 du 和 df 检查磁盘空间”">​</a></h3><p>在开始行动前，最好先检查一下是否磁盘上是否确实还有空间剩余。虽然桌面环境的工具也很不错，但命令行上的工具更直接，要好的多。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-du.jpg" alt="Linux Filesystem du" title="Linux Filesystem du"></p><p>首先让我们看看 <code>du</code> 命令。用它来检查问题磁盘所在的挂载点目录。本文假设出问题的分区挂载点为根目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo du -sh /</span></span></code></pre></div><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-df.jpg" alt="Linux Filesystem df" title="Linux Filesystem df"></p><p>由于它要遍历磁盘中的所有文件，因此需要花费一点时间。现在再让我们试试 <code>df</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo df -h</span></span></code></pre></div><p>把根目录和在其中挂载的文件系统加在这条命令的后面。比如，若你的有一个独立的磁盘挂载到 <code>/home</code>，那么除了根目录之外，你也需要把它加进来。使用空间的总和应该跟你 <code>du</code> 命令得到的结果接近。否则的话，就说明可能有已删除文件的文件被进程占用。</p><p>当然，这里主要专注点在于这些命令的结果是否要小于磁盘的大小。如果确实小于磁盘大小，那么很明显有很多地方不对劲。</p>',13)),i("p",null,[e[1]||(e[1]=i("strong",null,"相关",-1)),e[2]||(e[2]=s("：",-1)),a(t,{href:"https://www.maketecheasier.com/agedu-analyze-hard-disk-space-usage-in-linux/",title:"Use Agedu to Analyze Hard Disk Space Usage in Linux"},{default:l(()=>[...e[0]||(e[0]=[s("使用 Agedu 分析硬盘空间使用状况 ",-1)])]),_:1})]),e[20]||(e[20]=n('<h3 id="可能的原因" tabindex="-1">可能的原因 <a class="header-anchor" href="#可能的原因" aria-label="Permalink to “可能的原因”">​</a></h3><p>这里列出了一些产生这种情况的主要原因。若你发现 <code>du</code> 和 <code>df</code> 的结果之间有差别，那么可以直接检查第一项原因。否则从第二项原因开始检查。</p><h4 id="已删除文件被进程所占用" tabindex="-1">已删除文件被进程所占用 <a class="header-anchor" href="#已删除文件被进程所占用" aria-label="Permalink to “已删除文件被进程所占用”">​</a></h4><p>有时，文件可能已经被删掉了，但有进程依然在使用它。在进程运行期间，Linux 不会释放该文件的存储空间。你需要找出这个进程然后重启这个进程。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-process.jpg" alt="Check processes for deleted files" title="Check processes for deleted files"></p><p>使用下面命令来定位进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo lsof / | grep deleted</span></span></code></pre></div><p>这应该会列出出问题的进程了，然后重启该进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart service_name</span></span></code></pre></div><h4 id="i-节点不够了" tabindex="-1">i 节点不够了 <a class="header-anchor" href="#i-节点不够了" aria-label="Permalink to “i 节点不够了”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-inode.jpg" alt="Linux check filesystem inodes" title="Linux check filesystem inodes"></p><p>文件系统中有一些称为 “<ruby>i 节点<rt>inode</rt></ruby>” 的元数据，其用来保存文件的相关信息。很多文件系统中的 i 节点数量是固定的，因此很可能 i 节点已经耗尽了而文件系统本身还没有用完。你可以使用 <code>df</code> 来检查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo df -i /</span></span></code></pre></div><p>比较一下已用的 i 节点和总共的 i 节点数量。如果没有可用的 i 节点了，那么很不幸，你也无法扩充 i 节点。删除一些无用的和过期的文件来释放一些 i 节点吧。</p><h4 id="环块" tabindex="-1">环块 <a class="header-anchor" href="#环块" aria-label="Permalink to “环块”">​</a></h4><p>最后一个很常见的问题就是坏的文件系统块。除非另有标记，否则操作系统很可能会认为这些块都是可用的，这会导致文件系统损坏或者硬盘坏死。最好是使用带 <code>-cc</code> 标志的 <code>fsck</code> 搜索并标记出这些块。记住，你不能使用正在使用的文件系统（LCTT 译注：即包含坏块的文件系统）中的 <code>fsck</code> 命令。你应该会要用到 live CD。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fsck -vcck /dev/sda2</span></span></code></pre></div><p>很明显，这里需要使用你想检查的磁盘路径取代命令中的磁盘位置。另外，要注意，这恐怕会花上很长一段时间。</p>',18)),i("p",null,[e[4]||(e[4]=i("strong",null,"相关",-1)),e[5]||(e[5]=s("：",-1)),a(t,{href:"https://www.maketecheasier.com/check-repair-filesystem-fsck-linux/",title:"Check and Repair Your Filesystem With fsck [Linux]"},{default:l(()=>[...e[3]||(e[3]=[s("使用 fsck 检查并修复你的文件系统 [Linux]",-1)])]),_:1})]),e[21]||(e[21]=i("p",null,"希望这些方案能解决你的问题。这种问题在任何情况下都不是那么容易诊断的。但是，在运气好的情况下，你可以把文件系统清理干净并让你的硬盘再次正常工作。",-1)),e[22]||(e[22]=i("hr",null,null,-1)),i("p",null,[e[7]||(e[7]=s("via: ",-1)),a(t,{href:"https://www.maketecheasier.com/fix-linux-no-space-left-on-device-error/"},{default:l(()=>[...e[6]||(e[6]=[s("https://www.maketecheasier.com/fix-linux-no-space-left-on-device-error/",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=s("作者：",-1)),a(t,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:l(()=>[...e[8]||(e[8]=[s("Nick Congleton",-1)])]),_:1}),e[12]||(e[12]=s(" 译者：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[9]||(e[9]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[14]||(e[14]=[s("LCTT",-1)])]),_:1}),e[17]||(e[17]=s(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...e[15]||(e[15]=[s("Linux中国",-1)])]),_:1}),e[18]||(e[18]=s(" 荣誉推出",-1))])])}const L=o(u,[["render",h]]);export{w as __pageData,L as default};
